// This builder holds the only mutable directory borrow for its insertion loop.
// Its prefix is derived from exactly the keys that loop has inserted; it never
// authenticates a lookup or survives publication of the immutable directory.
pub(in crate::cleanup_plan::replay::expression_facts::receiving) struct HeldPrefix<'directory, 'hir>
{
    directory: &'directory mut Directory<&'hir StatusSourceId>,
    owner: Owner<'hir>,
    prefix: usize,
}
struct HeldSearch {
    probe: Probe,
    at: usize,
}
const HELD_SEARCH_BYTES: usize = 2 * size_of::<HeldSearch>()
    + size_of::<Result<Probe, Diagnostic>>()
    + size_of::<Probe>()
    + size_of::<usize>();
const HELD_COMPARISON_BYTES: usize = size_of::<Comparison<'static>>()
    + size_of::<Result<usize, Diagnostic>>()
    + 2 * size_of::<usize>()
    + size_of::<bool>()
    + size_of::<&StatusSourceId>();

impl<'hir> Directory<&'hir StatusSourceId> {
    pub(in crate::cleanup_plan::replay::expression_facts::receiving) fn held_prefix<'directory>(
        &'directory mut self,
        function: &'hir ResolvedFunction,
        budget: &mut ReplayBudget,
    ) -> Result<HeldPrefix<'directory, 'hir>, Diagnostic> {
        budget.reserve_bytes(
            function,
            2 * size_of::<HeldPrefix<'_, '_>>()
                + size_of::<Result<HeldPrefix<'_, '_>, Diagnostic>>(),
            self.phase,
        )?;
        // Directory borrow, existing owner, and prefix initialization.
        budget.charge(function, 3, self.phase)?;
        let owner = Owner::new(function, self, budget)?;
        Ok(HeldPrefix {
            directory: self,
            owner,
            prefix: 0,
        })
    }

    fn held_probe(
        &self,
        function: &ResolvedFunction,
        key: &StatusSourceId,
        prefix: usize,
        budget: &mut ReplayBudget,
    ) -> Result<Probe, Diagnostic> {
        budget.reserve_bytes(function, HELD_SEARCH_BYTES, self.phase)?;
        // Two search fields, five nested probe fields, one received prefix.
        budget.charge(function, 8, self.phase)?;
        let mut search = HeldSearch {
            probe: Probe {
                found: false,
                parent: NIL,
                before: NIL,
                after: NIL,
                side: Ordering::Equal,
            },
            at: self.root,
        };
        while search.at != NIL {
            budget.charge(function, VISIT_UNITS, self.phase)?;
            let node = &self.nodes[search.at];
            budget.charge(function, 1, self.phase)?;
            search.probe.side = compare(function, key, node.key, prefix, budget, self.phase)?.0;
            if search.probe.side == Ordering::Equal {
                budget.charge(function, 1, self.phase)?;
                search.probe.found = true;
                return Ok(search.probe);
            }
            budget.charge(function, 3, self.phase)?;
            search.probe.parent = search.at;
            if search.probe.side == Ordering::Less {
                search.probe.after = search.at;
                search.at = node.left;
            } else {
                search.probe.before = search.at;
                search.at = node.right;
            }
        }
        Ok(search.probe)
    }
}

impl<'hir> HeldPrefix<'_, 'hir> {
    fn common_prefix(
        &self,
        function: &ResolvedFunction,
        key: &StatusSourceId,
        budget: &mut ReplayBudget,
    ) -> Result<usize, Diagnostic> {
        let phase = self.directory.phase;
        budget.reserve_bytes(function, HELD_COMPARISON_BYTES, phase)?;
        budget.charge(function, VISIT_UNITS, phase)?;
        let minimum = self.directory.nodes[self.directory.first].key;
        // The existing Comparison setup plus one clamp to the held bound.
        budget.charge(function, COMPARISON_UNITS + 1, phase)?;
        let mut comparison = Comparison {
            left: key.expression.as_str().as_bytes(),
            right: minimum.expression.as_str().as_bytes(),
            end: key
                .expression
                .as_str()
                .len()
                .min(minimum.expression.as_str().len())
                .min(self.prefix),
            common: 0,
        };
        let units = comparison.end.checked_add(1).ok_or_else(|| {
            overflow(
                function,
                budget,
                "held status prefix comparison work overflow",
            )
        })?;
        budget.charge(function, units, phase)?;
        while comparison.common < comparison.end {
            if comparison.left[comparison.common] != comparison.right[comparison.common] {
                return Ok(comparison.common);
            }
            comparison.common += 1;
        }
        Ok(comparison.common)
    }

    pub(in crate::cleanup_plan::replay::expression_facts::receiving) fn insert(
        &mut self,
        function: &ResolvedFunction,
        key: &'hir StatusSourceId,
        budget: &mut ReplayBudget,
    ) -> Result<bool, Diagnostic> {
        let phase = self.directory.phase;
        let result = (|| {
            self.owner
                .authenticate(self.directory, function, key, budget)?;
            self.directory.authenticate(function, budget)?;
            budget.charge(function, 1, phase)?;
            if self.directory.nodes.is_empty() {
                budget.reserve_bytes(function, size_of::<usize>(), phase)?;
                budget.charge(function, 2, phase)?;
                let prefix = key.expression.as_str().len();
                let inserted = self.directory.insert(function, key, budget)?;
                budget.charge(function, 1, phase)?;
                if inserted {
                    self.prefix = prefix;
                }
                return Ok(inserted);
            }
            let prefix = self.common_prefix(function, key, budget)?;
            let probe = self.directory.held_probe(function, key, prefix, budget)?;
            if probe.found {
                return Ok(false);
            }
            self.directory.grow(function, budget)?;
            budget.charge(function, VISIT_UNITS, self.directory.phase)?;
            let index = self.directory.nodes.len();
            self.directory.nodes.push(Node {
                key,
                left: NIL,
                right: NIL,
                parent: probe.parent,
                next: probe.after,
                height: 1,
            });
            if probe.before == NIL {
                self.directory.first = index;
            } else {
                self.directory.nodes[probe.before].next = index;
            }
            if probe.parent == NIL {
                self.directory.root = index;
            } else if probe.side == Ordering::Less {
                self.directory.nodes[probe.parent].left = index;
            } else {
                self.directory.nodes[probe.parent].right = index;
            }
            self.directory.rebalance(probe.parent, function, budget)?;
            budget.charge(function, 1, phase)?;
            self.prefix = prefix;
            Ok(true)
        })();
        match result {
            Ok(inserted) => {
                budget.charge(function, 1, phase).inspect_err(|_| {
                    self.owner.first.set(Some(Refusal::Budget));
                })?;
                self.owner.next.set(self.owner.next.get() + 1);
                Ok(inserted)
            }
            Err(error) => {
                if self.owner.first.get().is_none() {
                    self.owner.first.set(Some(Refusal::Budget));
                }
                Err(error)
            }
        }
    }
}

#[test]
fn held_prefix_keeps_every_original_link_and_shrinks_only_from_current_keys() {
    let names = [
        "shared.é.000",
        "shared.é.002",
        "shared.é.001",
        "shared.é.000",
        "shared.è",
        "shared.\0",
        "a",
        "",
        "界",
    ];
    let keys = names
        .iter()
        .flat_map(|name| {
            [
                StatusLane::OperationFailure,
                StatusLane::OwnerAdmission,
                StatusLane::ContractFalse,
                StatusLane::AllocationFailure,
            ]
            .map(|lane| (*name, lane))
        })
        .collect::<Vec<_>>();
    let function = function(&keys);
    let (((), allocation), refused, paid, first) = with_limit_usage_refusal(usize::MAX, || {
        measure(|| {
            let mut old_budget = ReplayBudget::new();
            let mut budget = ReplayBudget::new();
            let mut old = Directory::new(
                &function,
                &mut old_budget,
                "cleanup status identity directory",
            )
            .unwrap();
            let mut current =
                Directory::new(&function, &mut budget, "cleanup status identity directory")
                    .unwrap();
            let owner = Owner::new(&function, &old, &mut old_budget).unwrap();
            let mut held = current.held_prefix(&function, &mut budget).unwrap();
            for source in &function.cleanup_plan.status_sources {
                let expected = old
                    .insert_certified(&function, &source.id, &mut old_budget, &owner)
                    .unwrap();
                assert_eq!(
                    held.insert(&function, &source.id, &mut budget).unwrap(),
                    expected
                );
                same_tree(&old, held.directory);
                let mut keys = held.directory.keys();
                let first = keys.next().unwrap().expression.as_str().as_bytes();
                let mut common = first.len();
                for key in keys {
                    common = first[..common]
                        .iter()
                        .zip(key.expression.as_str().as_bytes())
                        .take_while(|(left, right)| left == right)
                        .count();
                }
                assert_eq!(held.prefix, common);
            }
            drop(held);
            drop(owner);
            drop(current);
            drop(old);
            drop(budget);
            drop(old_budget);
        })
    });
    assert!(!refused && first.is_none());
    assert!(!allocation.invalid && allocation.live == 0);
    assert_eq!(allocation.allocated, allocation.freed);
    assert!(allocation.allocated <= paid);
}

#[test]
fn held_prefix_preserves_physical_frontiers_and_final_drop_without_a_new_allowance() {
    let names = (0..128)
        .rev()
        .map(|index| format!("{}.{index:06}", "common.é".repeat(24)))
        .collect::<Vec<_>>();
    let keys = names
        .iter()
        .map(|name| (name.as_str(), StatusLane::OperationFailure))
        .collect::<Vec<_>>();
    let function = function(&keys);
    let observe = |held, available, floor| {
        with_limit_usage_refusal(available + floor, || {
            assert!(crate::bounded_output::set_active_floor(floor));
            measure(|| {
                let mut budget = ReplayBudget::new();
                let start = budget.remaining;
                let result = (|| {
                    let mut directory = Directory::new(
                        &function,
                        &mut budget,
                        "cleanup status identity directory",
                    )?;
                    if held {
                        let mut builder = directory.held_prefix(&function, &mut budget)?;
                        for source in &function.cleanup_plan.status_sources {
                            assert!(builder.insert(&function, &source.id, &mut budget)?);
                        }
                        drop(builder);
                    } else {
                        let owner = Owner::new(&function, &directory, &mut budget)?;
                        for source in &function.cleanup_plan.status_sources {
                            assert!(directory.insert_certified(
                                &function,
                                &source.id,
                                &mut budget,
                                &owner
                            )?);
                        }
                        drop(owner);
                    }
                    assert_eq!(directory.len(), 128);
                    assert!(directory.balanced());
                    drop(directory);
                    Ok::<_, Diagnostic>(())
                })();
                let ok = result.is_ok();
                let work = start - budget.remaining;
                drop(result);
                if !ok {
                    assert!(budget
                        .reserve_bytes(&function, 0, "sticky held prefix")
                        .is_err());
                }
                drop(budget);
                (ok, work)
            })
        })
    };
    let (((ok, old_work), old), refused, old_bytes, first) = observe(false, usize::MAX, 0);
    assert!(ok && !refused && first.is_none());
    let (((ok, new_work), new), refused, exact, first) = observe(true, usize::MAX, 0);
    assert!(ok && !refused && first.is_none());
    assert!(new_work < old_work && exact < old_bytes);
    assert_eq!(new.allocated, old.allocated);
    for allocation in [old, new] {
        assert!(!allocation.invalid && allocation.live == 0);
        assert_eq!(allocation.allocated, allocation.freed);
    }
    for floor in [0, 37] {
        for available in [0, exact - 1, exact] {
            let (((ok, _), allocation), refused, spent, first) = observe(true, available, floor);
            assert_eq!(ok, available == exact);
            assert_eq!(refused, !ok);
            assert_eq!(first.is_some(), !ok);
            if let Some(first) = first {
                assert_eq!(first.floor, floor);
            }
            assert!(spent <= available && allocation.allocated <= spent);
            assert!(!allocation.invalid && allocation.live == 0);
            assert_eq!(allocation.allocated, allocation.freed);
            if available == 0 {
                assert_eq!(allocation.allocated, 0);
            }
        }
    }
}

