// Same complete validation loop; only the owned insertion builder differs.
pub(in crate::cleanup_plan::replay) fn validate_status_sources_held_prefix<'hir>(
    function: &'hir ResolvedFunction,
    facts: &Facts<'_>,
    budget: &mut ReplayBudget,
) -> Result<StatusSources<'hir>, Diagnostic> {
    if let Facts::Tree(tree) = facts {
        super::super::super::validate_status_sources(function, tree)?;
        budget.reserve_bytes(function, CONTROL_BYTES, "retained status full controls")?;
        return Ok(StatusSources {
            function,
            budget,
            ledger: ClassifierLedger::capture(),
            ids: None,
        });
    }
    let expressions: &dyn Lookup = facts;
    let mut ids = Directory::new(function, budget, "cleanup status identity directory")?;
    let mut prefix_owner = ids.held_prefix(function, budget)?;
    for source in &function.cleanup_plan.status_sources {
        if !prefix_owner.insert(function, &source.id, budget)? {
            return Err(<Diagnostic as semantic_refusal::Error>::structural(
                function,
                semantic_refusal::Atom::RepeatedStatus(source.id.expression.clone()),
            ));
        }
        // Retain the actual first lookup's borrowed payload, only through this
        // immutable source's producer match. Pay its complete receiving pointer
        // and one assignment step; no previous result/header credit is used.
        budget.reserve_bytes(
            function,
            std::mem::size_of::<&Option<CallFact<'_>>>(),
            "retained status fact receiving control",
        )?;
        budget.charge(function, 1, "retained status fact receiving assignment")?;
        let Some(fact) = expressions.fact(function, &source.id.expression, budget)? else {
            return Err(<Diagnostic as semantic_refusal::Error>::structural(
                function,
                semantic_refusal::Atom::UnknownStatus(source.id.expression.clone()),
            ));
        };
        match (&source.id.lane, &source.producer) {
            (
                StatusLane::OperationFailure | StatusLane::OwnerAdmission,
                StatusProducer::PropagatedCall { callee },
            ) => {
                // The payload reference is a second simultaneous receiving
                // control; the eliminated lookup's result is not a credit.
                budget.reserve_bytes(
                    function,
                    std::mem::size_of::<&CallFact<'_>>(),
                    "retained status call receiving control",
                )?;
                budget.charge(function, 1, "retained status call receiving assignment")?;
                let Some(call) = fact else {
                    return Err(replay_error(
                        function,
                        "propagated-call status source does not name a call expression",
                    ));
                };
                if call.callee.as_ref() != callee {
                    return Err(replay_error(
                        function,
                        "propagated-call status source names the wrong callee",
                    ));
                }
            }
            (
                StatusLane::OperationFailure,
                StatusProducer::CheckedArithmetic {
                    normalized_cases, ..
                },
            ) => {
                let mut cases = Directory::new(
                    function,
                    budget,
                    "cleanup checked arithmetic case directory",
                )?;
                for case in normalized_cases {
                    cases.insert(function, *case, budget)?;
                }
                if cases.is_empty() || cases.len() != normalized_cases.len() {
                    return Err(replay_error(
                        function,
                        "checked-arithmetic status cases are empty or repeated",
                    ));
                }
            }
            (
                StatusLane::AllocationFailure,
                StatusProducer::CheckedAllocation {
                    normalized_cases, ..
                },
            ) if function.cleanup_plan.schema == crate::cleanup_plan::CLEANUP_PLAN_SCHEMA_V20
                && *normalized_cases
                    == [
                        crate::cleanup_plan::AllocationCase::PayloadRefused,
                        crate::cleanup_plan::AllocationCase::SizeOverflow,
                    ] => {}
            (StatusLane::ContractFalse, StatusProducer::ContractFalse { .. }) => {}
            _ => {
                return Err(replay_error(
                    function,
                    "status source lane does not match its producer",
                ));
            }
        }
    }
    drop(prefix_owner);
    budget.reserve_bytes(function, CONTROL_BYTES, "retained status full controls")?;
    Ok(StatusSources {
        function,
        budget,
        ledger: ClassifierLedger::capture(),
        ids: Some(ids),
    })
}

// This direct borrowed predicate replaces the absent complete:false
// initializer in the unchanged, already-funded lexical begin frame.
if matches!(
    &budget.payer,
    &crate::cleanup_plan::replay::allocation::AllocationPayer::ActiveBuilder
        | &crate::cleanup_plan::replay::allocation::AllocationPayer::LegacyUnobserved
) {
    // Pay the complete new lexical selection receivers before length
    // inspection. This is an additional real fee, never credit from the proof
    // or either insertion owner. The tree lane above retains its old path.
    budget.reserve_bytes(
        function,
        3 * std::mem::size_of::<Result<(), Diagnostic>>()
            + 2 * std::mem::size_of::<(&mut ReplayBudget, &ResolvedFunction, &str, usize)>()
            + std::mem::size_of::<&ReplayBudget>()
            + std::mem::size_of::<&Vec<crate::cleanup_plan::StatusSource>>()
            + 2 * std::mem::size_of::<usize>()
            + 4 * std::mem::size_of::<bool>(),
        "certified held-prefix selection controls",
    )?;
    budget.charge(function, 2, "certified held-prefix selection")?;
    if function.cleanup_plan.status_sources.len() >= 3 {
        let mut prefix_owner = ids.held_prefix(function, budget)?;
        budget.reserve_bytes(
            function,
            std::mem::size_of::<usize>(),
            "status case row ordinal",
        )?;
        budget.charge(function, 1, "status case row ordinal")?;
        let mut ordinal = 0usize;
        // This paid ordinal advances only after the complete fallible row body.
        // A direct while-index keeps that frontier without an Enumerate carrier.
        while ordinal < function.cleanup_plan.status_sources.len() {
            let source = &function.cleanup_plan.status_sources[ordinal];
            if !prefix_owner.insert(function, &source.id, budget)? {
                return Err(<Diagnostic as semantic_refusal::Error>::structural(
                    function,
                    semantic_refusal::Atom::RepeatedStatus(source.id.expression.clone()),
                ));
            }
            // Retain the actual first lookup's borrowed payload, only through this
            // immutable source's producer match. Pay its complete receiving pointer
            // and one assignment step; no previous result/header credit is used.
            budget.reserve_bytes(
                function,
                std::mem::size_of::<&Option<CallFact<'_>>>(),
                "retained status fact receiving control",
            )?;
            budget.charge(function, 1, "retained status fact receiving assignment")?;
            let Some(fact) = expressions.fact(function, &source.id.expression, budget)? else {
                return Err(<Diagnostic as semantic_refusal::Error>::structural(
                    function,
                    semantic_refusal::Atom::UnknownStatus(source.id.expression.clone()),
                ));
            };
            match (&source.id.lane, &source.producer) {
                (
                    StatusLane::OperationFailure | StatusLane::OwnerAdmission,
                    StatusProducer::PropagatedCall { callee },
                ) => {
                    // The payload reference is a second simultaneous receiving
                    // control; the eliminated lookup's result is not a credit.
                    budget.reserve_bytes(
                        function,
                        std::mem::size_of::<&CallFact<'_>>(),
                        "retained status call receiving control",
                    )?;
                    budget.charge(function, 1, "retained status call receiving assignment")?;
                    let Some(call) = fact else {
                        return Err(replay_error(
                            function,
                            "propagated-call status source does not name a call expression",
                        ));
                    };
                    if call.callee.as_ref() != callee {
                        return Err(replay_error(
                            function,
                            "propagated-call status source names the wrong callee",
                        ));
                    }
                }
                (
                    StatusLane::OperationFailure,
                    StatusProducer::CheckedArithmetic {
                        normalized_cases, ..
                    },
                ) => {
                    // Complete independent discovery proved the exact held row.
                    // No case value is read here and no second case directory exists.
                    proof.member(function, source, ordinal, budget)?;
                    let _ = normalized_cases;
                }
                (
                    StatusLane::AllocationFailure,
                    StatusProducer::CheckedAllocation {
                        normalized_cases, ..
                    },
                ) if function.cleanup_plan.schema == crate::cleanup_plan::CLEANUP_PLAN_SCHEMA_V20
                    && *normalized_cases
                        == [
                            crate::cleanup_plan::AllocationCase::PayloadRefused,
                            crate::cleanup_plan::AllocationCase::SizeOverflow,
                        ] => {}
                (StatusLane::ContractFalse, StatusProducer::ContractFalse { .. }) => {}
                _ => {
                    return Err(replay_error(
                        function,
                        "status source lane does not match its producer",
                    ));
                }
            }
            budget.charge(function, 1, "status case row ordinal increment")?;
            ordinal += 1;
        }
        drop(prefix_owner);
        budget.reserve_bytes(function, CONTROL_BYTES, "retained status full controls")?;
        attempt.complete(function, budget)?;
        return Ok(StatusSources {
            function,
            budget,
            ledger: ClassifierLedger::capture(),
            ids: Some(ids),
        });
    }
}

#[test]
fn certified_unobserved_wide_dispatch_keeps_complete_rows_and_original_work_ceiling() {
    // Real HIR discovery must authenticate these rows: synthetic status tables
    // would not exercise the current certified production receiver.
    let prefix = "ordinary.shared.".repeat(4);
    let main_id = format!("{prefix}main");
    let mut source = format!(
        "module ordinary.wide;\n@id(\"wide.add\") fn add(x:i64)->i64 requires x>=0 ensures result>=0 {{x+1}}\n@id(\"{main_id}\") fn main()->i64 {{\n"
    );
    for n in 0..512 {
        source.push_str(&format!("let v{n}=add(0)+3-2*4/2%3;\n"));
    }
    source.push_str("-1}\n");
    let ast = crate::check(&source, "ordinary-wide-certified.spx").unwrap();
    let program = crate::hir::resolve(&ast).unwrap();
    let function = program.functions.iter().find(|f| f.name == "main").unwrap();
    assert!(function.cleanup_plan.status_sources.len() >= 3000);
    let mut expected = function
        .cleanup_plan
        .status_sources
        .iter()
        .map(|source| &source.id)
        .collect::<Vec<_>>();
    expected.sort();
    assert!(expected
        .iter()
        .all(|id| id.expression.as_str().len() > prefix.len()));
    let mut preparation = ReplayBudget::unobserved();
    let facts = Facts::Arena(
        crate::cleanup_plan::replay::expression_facts::arena::build::<
            crate::cleanup_plan::replay::expression_facts::errors::Legacy,
        >(
            function,
            crate::cleanup_plan::replay::expression_facts::capacity::Payer::Selected(
                &mut crate::cleanup_plan::replay::physical_storage::PhysicalReservation::new(
                    usize::MAX,
                ),
            ),
            &mut preparation,
        )
        .unwrap(),
    );
    let observe = |old| {
        let ((ok, remaining), allocation) = crate::test_allocation_observer::measure(|| {
            let mut budget = ReplayBudget::unobserved();
            assert!(matches!(
                budget.payer,
                crate::cleanup_plan::replay::allocation::AllocationPayer::LegacyUnobserved
            ));
            let result = (|| {
                let proof = StatusCases::validate(&program, function, &mut budget)?;
                let sources = if old {
                    counter_before::validate_status_sources_certified(
                        function,
                        &facts,
                        &mut budget,
                        &proof,
                    )?
                } else {
                    validate_status_sources_certified(function, &facts, &mut budget, &proof)?
                };
                let ids = sources.ids.as_ref().unwrap();
                assert_eq!(ids.len(), expected.len());
                assert!(ids.keys().copied().eq(expected.iter().copied()));
                drop(sources);
                drop(proof);
                Ok::<_, crate::diagnostic::Diagnostic>(())
            })();
            let ok = result.is_ok();
            drop(result);
            let remaining = budget.remaining;
            drop(budget);
            (ok, remaining)
        });
        assert!(!allocation.invalid && allocation.live == 0);
        assert_eq!(
            allocation.allocated, allocation.freed,
            "actual receiver, proof, diagnostic and last Drop stay observed"
        );
        (ok, remaining)
    };
    let before = observe(true);
    let current = observe(false);
    assert!(
        current.0,
        "actual certified unobserved route fits the unchanged ceiling"
    );
    assert!(current.1 > 0 && current.1 < MAX_REPLAY_WORK_UNITS);
    assert!(
        current.1 > before.1,
        "the actual held-prefix dispatch saves work against the complete counter receiver"
    );
}

//! Authority comes only from complete independent typed-HIR status discovery.
//! This affine proof borrows the immutable table, never its names as authority.
use super::{ClassifierLedger, Diagnostic, ReplayBudget, ResolvedFunction, StatusSource};
use std::cell::Cell;
use std::mem::size_of;

pub(super) const PHASE: &str = "complete status case proof";

#[derive(Clone, Copy, Eq, PartialEq)]
pub(super) enum State {
    Ready,
    Active,
    Finished,
    Failed,
}

pub(in crate::cleanup_plan::replay) struct StatusCases<'hir> {
    function: &'hir ResolvedFunction,
    rows: &'hir [StatusSource],
    budget: *const ReplayBudget,
    ledger: ClassifierLedger,
    pub(super) state: Cell<State>,
}

// Affine receiving attempt: every early error/unwind poisons the held proof.
pub(super) struct Attempt<'proof, 'hir> {
    proof: &'proof StatusCases<'hir>,
    complete: bool,
}
#[cfg(test)]
impl Attempt<'_, '_> {
    pub(super) fn complete(
        &mut self,
        function: &ResolvedFunction,
        budget: &mut ReplayBudget,
    ) -> Result<(), Diagnostic> {
        self.proof.authenticate(function, budget)?;
        if self.proof.state.get() != State::Active {
            return Err(self.proof.reject());
        }
        budget.reserve_bytes(function, size_of::<Result<(), Diagnostic>>(), PHASE)?;
        budget.charge(function, 2, PHASE)?;
        self.proof.state.set(State::Finished);
        self.complete = true;
        Ok(())
    }
}
impl Drop for Attempt<'_, '_> {
    fn drop(&mut self) {
        if !self.complete {
            self.proof.state.set(State::Failed);
        }
    }
}

impl<'hir> StatusCases<'hir> {
    pub(in crate::cleanup_plan::replay) fn validate(
        program: &dyn crate::cleanup::ReplayContext,
        function: &'hir ResolvedFunction,
        budget: &mut ReplayBudget,
    ) -> Result<Self, Diagnostic> {
        // Keep the entire independent walk, including its late HIR-error priority.
        // No certificate, new payer request or early table mismatch precedes it.
        crate::cleanup_plan::replay::validate_required_status_sources(program, function)?;
        // Initializer, returned Result and actual caller's held receiving token.
        // An error from the old walk above is forwarded unchanged, not republished.
        budget.reserve_bytes(
            function,
            2 * size_of::<Self>() + size_of::<Result<Self, Diagnostic>>(),
            PHASE,
        )?;
        budget.charge(function, 5, PHASE)?;
        Ok(Self {
            function,
            rows: &function.cleanup_plan.status_sources,
            budget,
            ledger: ClassifierLedger::capture(),
            state: Cell::new(State::Ready),
        })
    }

    // Do not consult/debit a foreign payer or format text after selected refusal.
    // The first actual byte/work diagnostic is returned unchanged to its caller;
    // subsequent attempts retain H006 and cannot publish another acquisition.
    pub(super) fn reject(&self) -> Diagnostic {
        self.state.set(State::Failed);
        Diagnostic::io("SPX-H006", String::new())
    }

    pub(super) fn authenticate(
        &self,
        function: &ResolvedFunction,
        budget: &mut ReplayBudget,
    ) -> Result<(), Diagnostic> {
        if matches!(self.state.get(), State::Failed | State::Finished)
            || !std::ptr::eq(self.function, function)
            || !std::ptr::eq(self.budget, budget)
        {
            return Err(self.reject());
        }
        if !self.ledger.current() {
            return Err(self.reject());
        }
        // The zero request authenticates the original owner's sticky state.
        let result = budget
            .reserve_bytes(function, 0, PHASE)
            .and_then(|()| budget.charge(function, 0, PHASE))
            .and_then(|()| {
                budget.reserve_bytes(function, size_of::<Result<(), Diagnostic>>(), PHASE)
            });
        if result.is_err() {
            self.state.set(State::Failed);
        }
        result
    }

    #[cfg(test)]
    pub(super) fn begin<'proof>(
        &'proof self,
        function: &ResolvedFunction,
        budget: &mut ReplayBudget,
    ) -> Result<Attempt<'proof, 'hir>, Diagnostic> {
        if self.state.get() != State::Ready {
            return Err(self.reject());
        }
        self.authenticate(function, budget)?;
        if let Err(error) = budget
            .reserve_bytes(
                function,
                2 * size_of::<Attempt<'_, '_>>() + size_of::<Result<Attempt<'_, '_>, Diagnostic>>(),
                PHASE,
            )
            .and_then(|()| budget.charge(function, 3, PHASE))
        {
            self.state.set(State::Failed);
            return Err(error);
        }
        self.state.set(State::Active);
        Ok(Attempt {
            proof: self,
            complete: false,
        })
    }

    pub(super) fn member(
        &self,
        function: &ResolvedFunction,
        source: &StatusSource,
        ordinal: usize,
        budget: &mut ReplayBudget,
    ) -> Result<(), Diagnostic> {
        self.authenticate(function, budget)?;
        if self.state.get() != State::Active {
            return Err(self.reject());
        }
        // Inner actual lookup receipt and the successful outer member Result.
        // Neither the old directory's controls nor prior auth are a credit.
        let result = budget
            .reserve_bytes(
                function,
                size_of::<Option<&StatusSource>>() + size_of::<Result<(), Diagnostic>>(),
                PHASE,
            )
            .and_then(|()| budget.charge(function, 2, PHASE));
        if let Err(error) = result {
            self.state.set(State::Failed);
            return Err(error);
        }
        let held = self.rows.get(ordinal);
        if held.is_none_or(|held| !std::ptr::eq(held, source)) {
            return Err(self.reject());
        }
        Ok(())
    }
}

