            SOURCE.replace("->T {one}", "->T {two}"),
            SOURCE.replace("{first<T>(one,two)}", "{other<T>(one,two)}"),
        ] {
            let current = parse(&source);
            assert!(function_reuse_environment_is_exact(&current, &previous));
            parity(&current, &previous, &old, &costs);
        }
