        &self,
        function: &FunctionExecutionId,
        path: impl Into<ExprPath<'p>>,
        span: crate::ast::Span,
        callable: ResolvedExpr,
        args: Vec<ResolvedExpr>,
    ) -> Result<ResolvedExpr, Diagnostic> {
        finish(self.program, function, path, span, callable, args)
    }
