            id: path.into().expression_id(function),
            ty,
            ownership: OwnershipMode::Value,
            kind: ResolvedExprKind::FunctionReference {
                target: self.declarations.held_identity(&target.stable_id),
            },
            span: expr.span,
        }))
    }
