        || declarations.declaration(declaration).is_none_or(|item| {
            item.kind != DeclarationKind::Record || item.identity_origin != IdentityOrigin::Explicit
        })
        || declarations
            .type_parameters(declaration)
            .is_none_or(|parameters| !parameters.is_empty())
    {
        return false;
