            (
                K::Block { statements, .. } | K::VecConstructor { statements, .. },
                Position::Block { statement, child },
            ) if self.started && child != 0 => {
                statements.get(statement).map(|item| (item, child - 1))
            }
            _ => None,
        }
    }
    pub(crate) fn is_started(&self) -> bool {
        self.started
    }
}
