        let child_fields = self.declarations.record_fields(child).ok_or_else(|| {
            self.error("SPX-H006", format!("class `{child}` has no fields"), span)
        })?;
        let parent_fields = self.declarations.record_fields(parent).ok_or_else(|| {
            self.error("SPX-H006", format!("class `{parent}` has no fields"), span)
        })?;
        if child_fields.len() < parent_fields.len()
            || child_fields[..parent_fields.len()]
                .iter()
                .zip(parent_fields.iter())
                .any(|(child_field, parent_field)| child_field.id != parent_field.id)
        {
            return Err(self.error(
                "SPX-H006",
                format!("class `{child}` prefix disagrees with ancestor `{parent}`"),
                span,
            ));
        }
        for field in &child_fields[parent_fields.len()..] {
            let drops = self
                .declarations
                .type_flags(&field.ty)
                .is_some_and(|facts| facts.needs_drop);
            if drops {
                return Err(self.error(
                    "SPX-T233",
                    format!(
                        "upcast from `{child}` to `{parent}` would discard owned field `{}`; only cleanup-inert child fields are admitted in this slice",
                        field.name
                    ),
                    span,
                ));
            }
        }
        Ok(())
    }

    pub(super) fn expression_ownership(
        &self,
        ty: &ResolvedType,
        non_copy_mode: OwnershipMode,
        span: Span,
    ) -> Result<OwnershipMode, Diagnostic> {
        self.declarations
            .type_flags(ty)
            .map(|facts| {
                if facts.copy {
                    OwnershipMode::Value
                } else {
                    non_copy_mode
                }
            })
            .ok_or_else(|| {
                self.error(
                    "SPX-H004",
                    format!(
                        "semantic facts are unavailable for type `{}`",
                        ty.identity_key()
                    ),
                    span,
                )
            })
    }

    pub(super) fn function_expression_ownership(
        &self,
        function: &super::FunctionExecutionId,
        ty: &ResolvedType,
        non_copy_mode: OwnershipMode,
        span: Span,
    ) -> Result<OwnershipMode, Diagnostic> {
        if let super::FunctionExecutionId::Monomorphic(owner) = function {
            if let Some(template) = self.program.functions().iter().find(|candidate| {
                candidate.stable_id == owner.as_str() && !candidate.type_parameters.is_empty()
            }) {
                if super::generic_variant::slot(
                    &self.declarations,
                    ty,
                    owner,
                    template.type_parameters.len(),
                ) || super::generic_collection::slot(ty, owner, template.type_parameters.len())
                    || super::generic_result::slot(ty, owner, template.type_parameters.len())
                {
                    return Ok(non_copy_mode);
                }
                if super::type_reachability::is_nested_owned_byte_record_template(
                    &self.declarations,
                    ty,
                    owner,
                    template.type_parameters.len(),
                ) {
                    return Ok(non_copy_mode);
                }
                if matches!(ty, ResolvedType::TypeParameter { owner: parameter_owner, index }
                    if parameter_owner == owner
                        && usize::try_from(*index).ok().is_some_and(|index| index < template.type_parameters.len()))
                {
                    return Ok(OwnershipMode::Value);
                }
            }
        }
        self.expression_ownership(ty, non_copy_mode, span)
    }
}

