    scope.insert(
        item.to_owned(),
        Binding {
            traversal_row: None,
            id: ValueId::local(
                function,
                &format!("{path}.value.s1.body.s0.value.arm.1.binding.0"),
            ),
            ty: element.clone(),
            ownership: crate::iterator_ops::item_ownership(&element, false),
