#[test]
fn template_selected_name_minimum_and_static_refusal_remain_complete() {
    let program = parsed(
        "module name.funding; @id(\"name.identity\") fn identity[T](value:T)->T {value} @id(\"name.main\") fn main()->i64 {0}",
        "name-funding.spx",
    );
    let prepared = resolver(&program);
    let function = &program.functions[0];
    let ordinary = prepared.resolve_function_template(function).unwrap();
    let (bounded, refused, minimum, first) = with_limit_usage_refusal(64 * 1024 * 1024, || prepared.resolve_function_template(function));
    assert!(!refused && first.is_none());
    assert_eq!(bounded.unwrap(), ordinary);
    assert!(minimum > function.name.len());
    for limit in [0, minimum - 1, minimum] {
        let baseline = with_limit_usage_refusal(limit, || prepared.resolve_function_template(function));
        let observed = with_limit_usage_refusal(limit, || {
            let result = prepared.resolve_function_template(function);
            if result.is_err() { assert!(!crate::bounded_output::reserve_active(0)); }
            result
        });
        assert_eq!(observed, baseline);
        let (result, refused, charged, first) = observed;
        if limit == minimum {
            assert!(!refused && first.is_none());
            assert_eq!(charged, minimum);
            assert_eq!(result.unwrap(), ordinary);
        } else {
            assert!(refused && first.is_some());
            let diagnostic = result.unwrap_err();
            assert_eq!(diagnostic.code, "SPX-H006");
            assert_eq!(diagnostic.message_owned_capacity(), 0);
            assert_eq!(diagnostic.path, None);
            assert_eq!(diagnostic.span, None);
            assert_eq!(diagnostic.help, None);
            assert_eq!(diagnostic.severity, crate::diagnostic::Severity::Error);
        }
    }
}

//! Assignment-target lowering and bounded-loop admission.
//!
//! Also owns the `resolve_expr` entry point that drives the iterative
//! expression resolver.

use std::collections::BTreeMap;

use crate::ast::{Expr, ExprKind, ParamMode, Span, Statement, Type};
use crate::diagnostic::Diagnostic;
use crate::source_verify::is_scalar_source_type;

use super::expr_nodes::ResolvedExpr;
use super::ids::{DeclarationId, FunctionExecutionId};
use super::monomorphize::substitute_type;
use super::nodes::{is_scalar_resolved_type, DeclarationKind, ResolvedBinding, ResolvedType};
use super::{Binding, Resolver};

