                    // by-value scalar parameters and a scalar result keep the
                    // loop cleanup-edge-free; everything else is rejected
                    // before any argument in the same order as the recursive
                    // admission scan.
                    let declared = self
                        .program
                        .functions()
                        .iter()
                        .find(|function| function.name == *name);
