                                        && self.resolve_type(&param.ty, expression.span).is_ok_and(
                                            |ty| {
                                                crate::hir::iterator_loop::is_owner_renewal_record(
                                                    &self.declarations,
                                                    &ty,
                                                )
                                            },
                                        ))
                                }));
