    result_admit: impl Fn(&ResolvedFunction, &ResolvedType) -> bool,
    lookup_work: usize,
    cursor: &mut ProofCursor<'a>,
) -> bool {
    cursor.frames.fill(None);
    prove_with_frames(
        target,
        &lookup,
        &param_admit,
        &result_admit,
        lookup_work,
        (&mut cursor.frames, WORK),
        &mut |_| Some(()),
