        // unit comes back unchanged and ends the walk at that unit.
        let mut units = Vec::new();
        let mut bytes = funded::payer::Payer::unlimited();
        assert!(matches!(
            checked_bindings_funded_with_work(&program, &deep, &mut |b| bytes.pay(b), &mut |u| {
                units.push(u);
