            .work
            .checked_sub(self.entries.len().checked_add(1).ok_or_else(error)?)
            .ok_or_else(error)?;
        if let Some((_, _, proved)) = self
            .entries
            .iter()
            .find(|(p, f, _)| p.subject().same(owner.subject()) && std::ptr::eq(*f, target))
        {
            return Ok(*proved);
        }
        if self.entries.len() == self.entries.capacity() {
