            owner,
            target,
            &lookup,
            &param,
            &result,
            lookup_work,
            self.cursor.as_deref_mut().ok_or_else(error)?,
        )
        .is_some();
        self.entries.push((owner, target, proved));
        Ok(proved)
    }
