    pub(crate) fn owned_capacity_bytes(&self) -> usize {
        self.entries.capacity() * std::mem::size_of::<Entry<'a>>()
            + self
                .cursor
                .as_ref()
                .map_or(0, |_| std::mem::size_of::<source::Cursor<'a>>())
    }
}
