struct IterativeVerifier<'a, 'v, 'p> {
    program: &'p dyn ProgramSource,
    current: &'v FunctionRef<'p>,
    constructor_hygiene: Option<bool>,
    byte_helpers: Option<&'a dyn crate::loop_calls::byte_writer::SourceHelpers>,
    functions: &'p crate::source_verify::function_map::FunctionMap<'p>,
    types: &'p TypeTable<'p>,
    result_type: Option<&'p Type>,
    allow_moves: bool,
    diagnostics: &'a mut Vec<Diagnostic>,
    scopes: Vec<VerifierScope>,
    recovery: recovery::Recovery<'p>,
    #[cfg(test)]
    recovery_legacy: bool,
    #[cfg(test)]
    operators_before_799: bool,
    #[cfg(test)]
    extended_before_799: bool,
    frames: Vec<VerifierFrame<'p>>,
    values: Vec<Option<CheckedValue>>,
    /// Byte spans of the `bytes_set` calls this function admits as a
    /// same-owner re-open, `buffer = bytes_set(buffer, index, value)`. Every
    /// other `bytes_set` buffer operand must still be the enclosing write-once
    /// chain's previous link. Statement scheduling records a site before the
    /// right-hand side is entered, so the call's own admission rule reads it in
    /// the ordinary order.
    buffer_reopen_sites: std::collections::BTreeSet<(usize, usize)>,
    /// How many `while`/`for` conditions or bodies enclose the frame being
    /// checked; Owned String Loops v2 narrows `match` scrutinees there.
    loop_depth: usize,
    /// Exact owned `for own` item bindings whose record payload may be matched
    /// inside the active loop body.
    owned_iterator_items: Vec<String>,
    /// The held selection's exact producer call, set only by the private
    /// `FusedConstructionV1` candidate route. `None` on every default path.
    fused_producer: Option<&'p Expr>,
    /// Byte spans of traversal-row arguments admitted as Row Loan v1 by
    /// their exact enclosing ordinary call before that argument is entered.
    row_loan_sites: std::collections::BTreeSet<(usize, usize)>,
}

/// Declared in the module root, rather than beside the frame loop, because the
/// interop builder pins the verifier frame and variant match state layouts to
/// this file.
impl<'a, 'v, 'p> IterativeVerifier<'a, 'v, 'p> {
    #[allow(clippy::too_many_arguments)]
    #[cfg(test)]
    fn new(
        program: &'p dyn ProgramSource,
        current: &'v FunctionRef<'p>,
        variables: HashMap<String, Binding>,
        functions: &'p crate::source_verify::function_map::FunctionMap<'p>,
        types: &'p TypeTable<'p>,
        result_type: Option<&'p Type>,
        allow_moves: bool,
        diagnostics: &'a mut Vec<Diagnostic>,
    ) -> Self {
        Self::new_ref(
            program,
            current,
            variables,
            functions,
            types,
            result_type,
            allow_moves,
            diagnostics,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn new_ref(
        program: &'p dyn ProgramSource,
        current: &'v FunctionRef<'p>,
        variables: HashMap<String, Binding>,
        functions: &'p crate::source_verify::function_map::FunctionMap<'p>,
        types: &'p TypeTable<'p>,
        result_type: Option<&'p Type>,
        allow_moves: bool,
        diagnostics: &'a mut Vec<Diagnostic>,
    ) -> Self {
        const { assert!(std::mem::size_of::<VerifierFrame<'static>>() == 320) };
        const { assert!(std::mem::size_of::<VariantMatchState<'static>>() == 312) };
        let local_borrow_count = variables
            .values()
            .filter(|binding| binding.borrow_origin.is_some())
            .count();
        let mut recovery = recovery::Recovery::signature(
            program,
            current.payload(),
            &variables,
            types,
            diagnostics,
        );
        declaration::record_shape::seed(
            &mut recovery,
            program,
            current.payload(),
            &variables,
            types,
            diagnostics,
        );
        Self {
            program,
            current,
            constructor_hygiene: None,
            byte_helpers: None,
            functions,
            types,
            result_type,
            allow_moves,
            diagnostics,
            scopes: vec![VerifierScope {
                bindings: variables,
                local_borrow_count,
            }],
            recovery,
            #[cfg(test)]
            recovery_legacy: false,
            #[cfg(test)]
            operators_before_799: false,
            #[cfg(test)]
            extended_before_799: false,
            frames: Vec::new(),
            values: Vec::new(),
            buffer_reopen_sites: std::collections::BTreeSet::new(),
            loop_depth: 0,
            owned_iterator_items: Vec::new(),
            fused_producer: None,
            row_loan_sites: std::collections::BTreeSet::new(),
        }
    }

    /// Record one admitted same-owner byte-buffer re-open before its
    /// right-hand side is entered.
    fn note_owned_buffer_reopen(&mut self, statement: &Statement) {
        if let Statement::Assign {
            name,
            field: None,
            value,
            ..
        } = statement
        {
            if crate::byte_ops::is_same_owner_set_shape(value, name) {
                self.buffer_reopen_sites
                    .insert((value.span.start, value.span.end));
            }
        }
    }
}

