        ExprKind::LexicalExit { value: None, .. } => {}
        ExprKind::Closure { .. } => {}
        ExprKind::Call {
            name,
            type_arguments,
            args,
        } => {
            for argument in args {
                check_omitted_generic_mappings(
                    program,
                    current,
                    argument,
                    bindings,
                    functions,
                    types,
                    diagnostics,
                    next,
                );
