                        program,
                        current,
                        value,
                        &mut scope,
                        functions,
                        types,
                        diagnostics,
                        next,
                    ),
                    Statement::Unsafe { body, .. } => check_omitted_generic_mappings(
                        program,
                        current,
                        body,
                        &mut scope,
                        functions,
                        types,
                        diagnostics,
                        next,
                    ),
                    Statement::While {
                        condition, body, ..
                    } => {
                        check_omitted_generic_mappings(
                            program,
                            current,
                            condition,
                            &mut scope,
                            functions,
                            types,
                            diagnostics,
                            next,
                        );
                        check_omitted_generic_mappings(
                            program,
                            current,
                            body,
                            &mut scope,
                            functions,
                            types,
                            diagnostics,
                            next,
                        );
