pub(super) fn check_ownership_mode_ref(
    program: &dyn ProgramSource,
    function: &crate::ast::program_source::FunctionRef<'_>,
    param: &crate::ast::Param,
    types: &TypeTable<'_>,
    diagnostics: &mut Vec<Diagnostic>,
) {
    if param.ty == Type::MutFunctionI64 {
        diagnostics.push(error(
            program,
            "SPX-T308",
            "mutable callback parameters are outside the local receiver profile",
            param.span,
        ));
        return;
    }
    if param.ty.is_once_function() {
        if param.mode != ParamMode::Own || !function.payload().type_parameters.is_empty() {
            diagnostics.push(error(
                program,
                "SPX-T308",
                "affine callable parameters require monomorphic `own FnOnce() -> i64`",
                param.span,
            ));
        }
        return;
    }
    if param.ty == Type::Str {
        if param.mode != ParamMode::Borrow {
            diagnostics.push(
                error(
                    program,
                    "SPX-O115",
                    format!(
                        "borrowed text parameter `{}.{}` must use `borrow str`",
                        function.name(),
                        param.name
                    ),
                    param.span,
                )
                .with_help(format!("use `{}: borrow str`", param.name)),
            );
        }
        return;
    }
    if param.ty == Type::SliceU8 {
        if param.mode != ParamMode::Borrow {
            diagnostics.push(
                error(
                    program,
                    "SPX-T263",
                    format!(
                        "byte-slice parameter `{}.{}` must use `borrow Slice<u8>`",
                        function.name(),
                        param.name
                    ),
                    param.span,
                )
                .with_help(format!("use `{}: borrow Slice<u8>`", param.name)),
            );
        }
        return;
    }
    if param.ty == Type::Bytes {
        if param.mode == ParamMode::Borrow && !function.payload().type_parameters.is_empty() {
            diagnostics.push(error(
                program,
                "SPX-T263",
                format!(
                    "borrowed Bytes parameter `{}.{}` requires a monomorphic function",
                    function.name(),
                    param.name
                ),
                param.span,
            ));
        } else if !matches!(param.mode, ParamMode::Own | ParamMode::Borrow) {
            diagnostics.push(error(
                program,
                "SPX-T263",
                format!(
                    "byte parameter `{}.{}` must use `own Bytes` or `borrow Bytes`",
                    function.name(),
                    param.name
                ),
                param.span,
            ));
        }
        return;
    }
    // Import stubs can declare parameters of appended private layout copies;
    // such a type is presented by provenance and never offered as a spelling.
    // Both are evaluated only while a diagnostic is constructed.
    let private = || super::private_names::is_private(program, types, &param.ty);
    let shown = || super::private_names::type_name(program, types, &param.ty);
    if types.is_direct_owned_variant(&param.ty) {
        if !matches!(param.mode, ParamMode::Own | ParamMode::Borrow) {
            let diagnostic = error(
                program,
                "SPX-T263",
                format!(
                    "owned-string variant parameter `{}.{}` must use `own {}` or `borrow {}`",
                    function.name(),
                    param.name,
                    shown(),
                    shown()
                ),
                param.span,
            );
            diagnostics.push(if private() {
                diagnostic
            } else {
                diagnostic.with_help(format!(
                    "use `{}: own {}` to transfer ownership, or `borrow {}` for a synchronous view",
                    param.name, param.ty, param.ty
                ))
            });
        }
        return;
    }
    if string_record::reject(program, &param.ty, "passed", param.span, types, diagnostics) {
        return;
    }
    let requires_explicit_mode = crate::map_ops::ast_collection(&param.ty)
        || string_record::runtime_admitted(&param.ty, types)
        || crate::stdin_stream_ops::ast_is_reader(&param.ty)
        || types.is_admitted_iterator(&param.ty)
        || types.contains_resource(&param.ty)
        || types.contains_owned_bytes(&param.ty)
        || matches!(&param.ty, Type::Named { name, arguments } if arguments.len() == 1 && types.declaration(name).is_some_and(|d| matches!(d.stable_id.as_str(), crate::prelude::BOX_ID | crate::prelude::VEC_ID)));
    match (requires_explicit_mode, param.mode) {
        (true, ParamMode::Value) => {
            let diagnostic = error(
                program,
                "SPX-O001",
                format!(
                    "resource parameter `{}.{}` needs `own`, `borrow`, or `shared`",
                    function.name(), param.name
                ),
                param.span,
            );
            diagnostics.push(if private() {
                diagnostic
            } else {
                diagnostic.with_help(format!(
                    "use `{}: own {}` to transfer ownership",
                    param.name, param.ty
                ))
            });
        }
        (false, mode) if mode != ParamMode::Value && param.ty == Type::String => diagnostics.push(
            error(
                program,
                "SPX-O002",
                "string parameters own their input implicitly; an explicit ownership mode is not admitted",
                param.span,
            )
            .with_help(format!(
                "use `{}: string` to transfer ownership; for a read-only helper, use `{}: borrow str` and pass `string_as_str(text)`",
                param.name, param.name
            )),
        ),
        (false, mode) if mode != ParamMode::Value => diagnostics.push(error(
            program,
            "SPX-O002",
            format!(
                "ownership mode `{}` is only valid for resource types; `{}` is a value type",
                mode.text(),
                shown()
            ),
            param.span,
        )),
        _ => {}
    }
}

pub(super) fn ordinary_result_arguments(ty: &Type) -> Option<(&Type, &Type)> {
    let Type::Named { name, arguments } = ty else {
        return None;
    };
    if name != "Result" || arguments.len() != 2 {
        return None;
    }
    Some((&arguments[0], &arguments[1]))
}

pub(super) fn ordinary_option_argument(ty: &Type) -> Option<&Type> {
    let Type::Named { name, arguments } = ty else {
        return None;
    };
    if name != "Option" || arguments.len() != 1 {
        return None;
    }
    Some(&arguments[0])
}

#[allow(clippy::too_many_arguments)]
pub(super) fn check_record_pattern(
    program: &dyn ProgramSource,
    pattern_type: &str,
    fields: &[RecordMatchPatternField],
    expected: &Type,
    variables: &mut HashMap<String, Binding>,
    types: &TypeTable<'_>,
    diagnostics: &mut Vec<Diagnostic>,
    span: Span,
    mode: MatchMode,
) {
    let expected_root = expected;
    let exact_recursive = mode != MatchMode::Value
        && (types.is_nested_owned_byte_record(expected)
            || string_record::runtime_admitted(expected, types))
        && !types.is_flat_owned_byte_record(expected);
    enum Frame<'a, 't> {
        Enter {
            pattern_type: &'a str,
            fields: &'a [RecordMatchPatternField],
            expected: Type,
            span: Span,
        },
        Fields {
            pattern_type: &'a str,
            fields: &'a [RecordMatchPatternField],
            expected: Type,
            declared_fields: &'t [FieldDeclaration],
            index: usize,
            supplied: HashSet<&'a str>,
            span: Span,
        },
    }

    let mut frames = vec![Frame::Enter {
        pattern_type,
        fields,
        expected: expected.clone(),
        span,
    }];
    while let Some(frame) = frames.pop() {
        match frame {
            Frame::Enter {
                pattern_type,
                fields,
                expected,
                span,
            } => {
                let compatible = matches!(
                    &expected,
                    Type::Named { name, .. } if name == pattern_type
                );
                let declared_fields = effective_record_fields(types, &expected);
                if !compatible
                    || declared_fields.is_none()
                    || (mode == MatchMode::Value && types.needs_drop(&expected))
                {
                    diagnostics.push(error(
                        program,
                        "SPX-M103",
                        format!(
                            "record pattern `{pattern_type}` is incompatible with `{}`",
                            super::private_names::type_name(program, types, &expected)
                        ),
                        span,
                    ));
                    continue;
                }
                frames.push(Frame::Fields {
                    pattern_type,
                    fields,
                    expected,
                    declared_fields: declared_fields.expect("checked above"),
                    index: 0,
                    supplied: HashSet::new(),
                    span,
                });
            }
            Frame::Fields {
                pattern_type,
                fields,
                expected,
                declared_fields,
                index,
                mut supplied,
                span,
            } => {
                let Some(field) = fields.get(index) else {
                    for declared in declared_fields {
                        if !supplied.contains(declared.name.as_str()) {
                            diagnostics.push(error(
                                program,
                                "SPX-M104",
                                format!(
                                    "record pattern `{pattern_type}` is missing field `{}`",
                                    declared.name
                                ),
                                span,
                            ));
                        }
                    }
                    continue;
                };
                let declared = declared_fields
                    .iter()
                    .find(|candidate| candidate.name == field.name);
                if !supplied.insert(field.name.as_str()) || declared.is_none() {
                    diagnostics.push(error(
                        program,
                        "SPX-M104",
                        format!(
                            "unknown or duplicate record pattern field `{}.{}`",
                            pattern_type, field.name
                        ),
                        field.span,
                    ));
                    frames.push(Frame::Fields {
                        pattern_type,
                        fields,
                        expected,
                        declared_fields,
                        index: index + 1,
                        supplied,
                        span,
                    });
                    continue;
                }
                let declared = declared.expect("checked above");
                let field_ty = types
                    .record_field_type(&expected, declared)
                    .unwrap_or_else(|| declared.ty.clone());
                frames.push(Frame::Fields {
                    pattern_type,
                    fields,
                    expected,
                    declared_fields,
                    index: index + 1,
                    supplied,
                    span,
                });
                match &field.pattern {
                    RecordMatchFieldPattern::Binding { name, span } => {
                        let subtree = mode == MatchMode::Own
                            && subtree::admitted(expected_root, &field_ty, types);
                        if exact_recursive
                            && !subtree
                            && !crate::map_ops::ast_collection(&field_ty)
                            && !collection_record::vector(types, &field_ty)
                            && types.record_fields(&field_ty).is_some()
                        {
                            diagnostics.push(error(
                                program,
                                "SPX-O117",
                                "nested owned-record fields require recursive record patterns",
                                *span,
                            ));
                        } else if !source_identifier(name) || variables.contains_key(name) {
                            diagnostics.push(error(
                                program,
                                "SPX-M104",
                                format!("invalid or duplicate record pattern binding `{name}`"),
                                *span,
                            ));
                        } else {
                            variables.insert(
                                name.clone(),
                                Binding {
                                    contract_local: false,
                                    traversal_row: None,
                                    mode: if types.needs_drop(&field_ty) {
                                        match mode {
                                            MatchMode::Own => ParamMode::Own,
                                            MatchMode::Borrow => ParamMode::Borrow,
                                            MatchMode::Value => ParamMode::Value,
                                        }
                                    } else {
                                        ParamMode::Value
                                    },
                                    ty: field_ty,
                                    availability: Availability::Available,
                                    moved_places: HashMap::new(),
                                    definitely_partial: HashSet::new(),
                                    native_unit_discard: false,
                                    mutable: false,
                                    active_loans: BTreeSet::new(),
                                    borrow_origin: None,
                                },
                            );
                        }
                    }
                    RecordMatchFieldPattern::Wildcard { span } => {
                        if (mode == MatchMode::Own || exact_recursive)
                            && types.needs_drop(&field_ty)
                        {
                            let message = if exact_recursive {
                                "exact owned-record patterns cannot wildcard an owned field"
                            } else {
                                "`match own` must bind every owned record field in this tranche"
                            };
                            diagnostics.push(error(program, "SPX-O117", message, *span));
                        }
                    }
                    RecordMatchFieldPattern::Record {
                        type_name,
                        fields,
                        span,
                        ..
                    } => frames.push(Frame::Enter {
                        pattern_type: type_name,
                        fields,
                        expected: field_ty,
                        span: *span,
                    }),
                }
            }
        }
    }
}

