pub(super) fn record_layout_is_recursive(
    name: &str,
    types: &TypeTable<'_>,
    visiting: &mut HashSet<String>,
    checked: &mut HashSet<String>,
) -> bool {
    enum Frame<'a> {
        Enter(&'a str),
        Fields {
            name: &'a str,
            fields: &'a [FieldDeclaration],
            parameters: HashSet<&'a str>,
            index: usize,
        },
    }

    let mut frames = vec![Frame::Enter(name)];
    let mut results = Vec::new();
    while let Some(frame) = frames.pop() {
        match frame {
            Frame::Enter(name) => {
                if checked.contains(name) {
                    results.push(false);
                    continue;
                }
                if !visiting.insert(name.to_owned()) {
                    results.push(true);
                    continue;
                }
                let Some(declaration) = types.declaration(name) else {
                    visiting.remove(name);
                    checked.insert(name.to_owned());
                    results.push(false);
                    continue;
                };
                let (TypeDeclarationKind::Record { fields }
                | TypeDeclarationKind::Class { fields, .. }) = &declaration.kind
                else {
                    visiting.remove(name);
                    checked.insert(name.to_owned());
                    results.push(false);
                    continue;
                };
                let parameters = declaration
                    .type_parameters
                    .iter()
                    .map(|parameter| parameter.name.as_str())
                    .collect::<HashSet<_>>();
                frames.push(Frame::Fields {
                    name,
                    fields,
                    parameters,
                    index: 0,
                });
            }
            Frame::Fields {
                name,
                fields,
                parameters,
                mut index,
            } => {
                if results.pop().unwrap_or(false) {
                    visiting.remove(name);
                    results.push(true);
                    continue;
                }
                let mut child = None;
                while let Some(field) = fields.get(index) {
                    index += 1;
                    let Type::Named {
                        name: field_type,
                        arguments,
                    } = &field.ty
                    else {
                        continue;
                    };
                    if arguments.is_empty() && parameters.contains(field_type.as_str()) {
                        continue;
                    }
                    if matches!(
                        types.declaration(field_type).map(|item| &item.kind),
                        Some(
                            TypeDeclarationKind::Record { .. } | TypeDeclarationKind::Class { .. }
                        )
                    ) {
                        child = Some(field_type.as_str());
                        break;
                    }
                }
                if let Some(child) = child {
                    frames.push(Frame::Fields {
                        name,
                        fields,
                        parameters,
                        index,
                    });
                    frames.push(Frame::Enter(child));
                } else {
                    visiting.remove(name);
                    checked.insert(name.to_owned());
                    results.push(false);
                }
            }
        }
    }
    results.pop().unwrap_or(false)
}

pub(super) fn check_declared_type(
    program: &dyn ProgramSource,
    ty: &Type,
    span: Span,
    types: &TypeTable<'_>,
    parameters: &HashSet<&str>,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let mut pending = vec![ty];
    while let Some(ty) = pending.pop() {
        if *ty == Type::Never {
            diagnostics.push(error(
                program,
                "SPX-T312",
                "lexical completion marker cannot appear in a declaration or storage type",
                span,
            ));
            continue;
        }
        if *ty == Type::MutFunctionI64 {
            if !parameters.is_empty() {
                diagnostics.push(error(
                    program,
                    "SPX-T308",
                    "mutable callables require monomorphic declarations",
                    span,
